// spec: .qa/e2e/specs/organizations-landing.md
// seed: tests/seed.hunter_plus.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

test.describe('/organizations — «publish tender» CTAs by role', () => {
  test('Logged-in headhunter: CTAs lead to /tenders, not to registration', async ({ page }) => {
    // 1. Open /organizations
    await page.goto('/organizations');
    await expect(page.getByRole('link', { name: 'לוח בקרה' })).toBeVisible();

    const ctas = page.locator('a[href="/publish/tender"]');
    await expect(ctas).toHaveCount(3);

    // 2. Click every tender-publish CTA (back between clicks)
    for (let i = 0; i < 3; i++) {
      if (i > 0) {
        await page.goto('/organizations');
      }
      await ctas.nth(i).scrollIntoViewIfNeeded();
      await ctas.nth(i).click();

      // Expected: /tenders, never /register, no wizard
      await expect(page).toHaveURL(/\/tenders$/);
      await expect(page).not.toHaveURL(/\/register/);
      await expect(page).not.toHaveURL(/\/publish\/tender/);
    }
  });
});
